package org.apache.commons.math.fraction;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.ZeroException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.ArithmeticUtils;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for {@link BigFraction#doubleValue()}.
 */
public class BigFraction_doubleValue_TriageGen3Test {

    private static final double EPSILON = 1e-15;

    @Test
    public void testDoubleValue_SimpleFraction() {
        BigFraction fraction = new BigFraction(1, 2);
        assertEquals(0.5, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValue_IntegerNumerator() {
        BigFraction fraction = new BigFraction(new BigInteger("10"), new BigInteger("2"));
        assertEquals(5.0, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValue_NegativeFraction() {
        BigFraction fraction = new BigFraction(-1, 4);
        assertEquals(-0.25, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValue_DoubleNegative() {
        BigFraction fraction = new BigFraction(-1, -2);
        assertEquals(0.5, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValue_ZeroNumerator() {
        BigFraction fraction = new BigFraction(0, 5);
        assertEquals(0.0, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValue_LargeValues() {
        // Testing values that are large but still within double range
        BigInteger num = new BigInteger("1000000000000000000");
        BigInteger den = new BigInteger("1000000000000000000");
        BigFraction fraction = new BigFraction(num, den);
        assertEquals(1.0, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValue_OverflowToInfinity() {
        // Test case where the result exceeds Double.MAX_VALUE
        // Using a very large numerator and a very small denominator (1)
        // Note: BigFraction stores BigInteger, so we can go way beyond double range
        BigInteger hugeNum = new BigInteger("1e308").multiply(new BigInteger("10")); 
        BigFraction fraction = new BigFraction(hugeNum, BigInteger.ONE);

        assertEquals(Double.POSITIVE_INFINITY, fraction.doubleValue(), 0.0);
    }

    @Test
    public void testDoubleValue_UnderflowToZero() {
        // Test case where the result is smaller than Double.MIN_VALUE
        BigInteger num = BigInteger.ONE;
        BigInteger hugeDen = new BigInteger("1").shiftLeft(2000); // Extremely large denominator
        BigFraction fraction = new BigFraction(num, hugeDen);

        assertEquals(0.0, fraction.doubleValue(), 0.0);
    }

    @Test
    public void testDoubleValue_PrecisionLoss() {
        // BigFraction can represent numbers more precisely than double.
        // This tests that the conversion follows standard double division behavior.
        // 1/3 in double is 0.3333333333333333
        BigFraction fraction = new BigFraction(1, 3);
        assertEquals(1.0 / 3.0, fraction.doubleValue(), 0.0);
    }

    @Test
    public void testDoubleValue_FromDoubleConstructor() {
        double val = 123.456;
        BigFraction fraction = new BigFraction(val);
        assertEquals(val, fraction.doubleValue(), EPSILON);
    }
}
